export async function getProductDetails(productId: string) {
  // Hard dependency: Must succeed or entire page fails
  const product = await catalogService.fetchById(productId);

  // Soft dependencies: Wrapped in safe error boundaries with fallbacks
  const [reviews, recommendations] = await Promise.all([
    reviewService.fetchReviews(productId).catch(() => {
      console.warn(`Review service unavailable for ${productId}; returning empty list`);
      return []; // Return empty review list
    }),
    recommendationService.fetchPersonalized(productId).catch(() => {
      // Fall back to pre-rendered static top-sellers
      return staticCatalog.getTopSellers();
    }),
  ]);

  return { ...product, reviews, recommendations };
}
